/* @lc app=leetcode id=3666 lang=kotlin */ class Solution { fun minOperations(s: String, k: Int): Int = s.count { it == '0' }.let { z -> s.length.let { n -> if (z == 0) 0 else (1..2 * n + 4).firstOrNull { t -> (t.toLong() * k) % 2 == z % 2L && t.toLong() * k >= z && t.toLong() * k <= z.toLong() * (if (t % 2 == 1) t else t - 1) + (n - z).toLong() * (if (t % 2 == 0) t else t - 1) } ?: -1 } } }